"""
in_statute_qa: questions about the Right to Information framework answered
from plain-language summaries of the Act, with citations, in the language
of the question.

The corpus is a set of summaries of the Right to Information Act, 2005,
the central RTI Rules, 2012 and a handful of leading court decisions,
written for this evaluation. They are NOT the statutory text and must be
verified against the Act before being relied on; they exist so the harness
can measure whether a model answers from the passage it was given, cites
it, refuses when the passages are silent, and does so in Hindi as well as
in English. Illustrative only; not legal advice.

Each passage is under 180 words so it is exactly one retrieval chunk
(`<doc_id>#0`). The evalset is answerable questions in English, Hindi and
Hinglish, hand-written unanswerable questions that are on-topic but not
covered, plus the harness's derived probes generated here with the
profile's settings so the file is a pure function of this script.

Idempotent: stable ids, same output every run.

    python data/in_statute_qa/build_dataset.py
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
sys.path.insert(0, str(ROOT))

from harness.eval.probes import ProbeConfig, build_probe_suite  # noqa: E402
from harness.profiles.loaders import load_evalset, save_evalset  # noqa: E402

CORPUS = HERE / "corpus.jsonl"
EVALSET = HERE / "evalset.jsonl"
BASE = HERE / "evalset_base.jsonl"

# Probe fractions mirror configs/profiles/in_statute_qa.yaml. Keep in step.
PROBES = ProbeConfig(unanswerable=0.15, noise=0.10, injection=0.15,
                     paraphrase=0.10, positional=0.0, n_distractors=3, seed=0)

DOCS: list[tuple[str, str]] = [
    ("s2_public_authority", "Section 2(h), Right to Information Act, 2005 (summary). A 'public authority' is any authority, body or institution of self-government established or constituted by or under the Constitution, by a law made by Parliament or a State Legislature, or by a notification or order of the appropriate Government. It also includes any body owned, controlled or substantially financed by the Government, and any non-government organisation substantially financed, directly or indirectly, by Government funds. The test for a body outside government is ownership, control or substantial financing, not the name of the body."),
    ("s2_information", "Section 2(f), Right to Information Act, 2005 (summary). 'Information' means any material in any form. The section lists records, documents, memos, e-mails, opinions, advices, press releases, circulars, orders, logbooks, contracts, reports, papers, samples, models and data held in any electronic form. It also includes information relating to any private body which a public authority can access under any other law in force. File notings and opinions recorded on a file are material in a form and therefore information."),
    ("s2_record_third_party", "Section 2(i) and 2(n), Right to Information Act, 2005 (summary). A 'record' includes any document, manuscript and file; any microfilm, microfiche and facsimile copy; any reproduction of an image embodied in such microfilm; and any other material produced by a computer or any other device. A 'third party' means a person other than the citizen making the request, and includes a public authority. So when an applicant asks one authority for records supplied by another authority, that other authority is a third party for the purposes of the Act."),
    ("s2_right_to_information", "Section 2(j), Right to Information Act, 2005 (summary). The right to information is the right to information accessible under the Act which is held by or under the control of any public authority. It includes the right to inspect works, documents and records; to take notes, extracts or certified copies of documents or records; to take certified samples of material; and to obtain information on diskettes, tapes, video cassettes or any other electronic mode, or through printouts, where the information is stored in a computer or other device."),
    ("s3_citizens", "Section 3, Right to Information Act, 2005 (summary). Subject to the provisions of the Act, all citizens have the right to information. The right belongs to citizens; the Act does not confer it on companies or associations as such, though the Commissions have generally accepted applications made by an individual citizen on behalf of an organisation. A non-citizen has no right under the Act."),
    ("s4_records_and_proactive", "Section 4(1)(a) and 4(2), Right to Information Act, 2005 (summary). Every public authority must maintain all its records duly catalogued and indexed in a manner that facilitates the right to information, and must computerise records appropriate for computerisation within a reasonable time, subject to resources, and connect them through a network so that access is facilitated. Every public authority must also make a constant endeavour to provide as much information as possible suo motu, at regular intervals, through the internet and other means, so that the public has minimum resort to the Act to obtain information."),
    ("s4_publication_list", "Section 4(1)(b), Right to Information Act, 2005 (summary). Within 120 days of enactment every public authority had to publish, and must keep updated, a set of seventeen categories of information: particulars of its organisation, functions and duties; the powers and duties of its officers and employees; the procedure followed in decision making including channels of supervision and accountability; the norms it sets for discharging its functions; its rules, regulations, instructions, manuals and records; the categories of documents it holds; arrangements for consultation with the public; its boards, councils and committees and whether their meetings are open; a directory of its officers; the monthly remuneration of each officer; its budget and disbursements; subsidy programmes with beneficiaries; recipients of concessions, permits and authorisations; information available in electronic form; facilities for citizens to obtain information; and the names and designations of its Public Information Officers."),
    ("s4_reasons_for_decisions", "Section 4(1)(c) and 4(1)(d), Right to Information Act, 2005 (summary). Every public authority must publish all relevant facts while formulating important policies or announcing decisions that affect the public, and must provide reasons for its administrative or quasi-judicial decisions to the persons affected by them. These are duties owed without any application; they sit alongside the request procedure of Section 6."),
    ("s5_pio_apio", "Section 5, Right to Information Act, 2005 (summary). Every public authority must designate as many Central or State Public Information Officers (PIOs) as needed to provide information to applicants, and must designate Assistant Public Information Officers at each sub-divisional or sub-district level to receive applications and appeals and forward them to the PIO or the appellate authority. The PIO must deal with requests and render reasonable assistance to applicants. A PIO may seek the assistance of any other officer, and that officer is then treated as a PIO for the purposes of any contravention of the Act."),
    ("s6_1_how_to_apply", "Section 6(1), Right to Information Act, 2005 (summary). A person seeking information makes a request in writing or through electronic means, in English or Hindi or in the official language of the area, to the PIO or Assistant PIO of the public authority concerned, specifying the particulars of the information sought and accompanied by the prescribed fee. Where a request cannot be made in writing, the PIO must render all reasonable assistance to the person to reduce it to writing. The Act does not prescribe a form; any written request with the particulars and the fee is an application."),
    ("s6_2_no_reasons", "Section 6(2), Right to Information Act, 2005 (summary). An applicant making a request for information is not required to give any reason for requesting the information, nor any other personal details except those necessary for contacting the applicant. A PIO may not reject or delay an application because the purpose is not stated, and may not ask why the information is wanted."),
    ("s6_3_transfer", "Section 6(3), Right to Information Act, 2005 (summary). Where an application is made to a public authority requesting information which is held by another public authority, or whose subject matter is more closely connected with the functions of another public authority, the receiving authority must transfer the application, or the relevant part of it, to that other authority and inform the applicant immediately. The transfer must be made as soon as practicable and in no case later than five days from the date of receipt of the application."),
    ("s7_1_time_limits", "Section 7(1), Right to Information Act, 2005 (summary). The PIO must, as expeditiously as possible and in any case within thirty days of receipt of the request, either provide the information on payment of the prescribed fee or reject the request for any of the reasons in Sections 8 and 9. Where the information sought concerns the life or liberty of a person, it must be provided within forty-eight hours of receipt. Where the application is given to an Assistant PIO, five days are added to these periods. Under Section 7(2), a PIO who fails to decide within the period is deemed to have refused the request."),
    ("s7_3_further_fee", "Section 7(3), Right to Information Act, 2005 (summary). Where the PIO decides to provide information on payment of a further fee representing the cost of providing it, the PIO sends the applicant an intimation giving the details of the further fee and the calculation used to arrive at it, asking the applicant to deposit the fee. The period between the dispatch of that intimation and the payment of the fee is excluded when calculating the thirty-day limit. The intimation must also inform the applicant of the right to seek review of the fee decision, including the particulars of the appellate authority, time limit, process and any other forms of access."),
    ("s7_5_6_fee_rules", "Section 7(5) and 7(6), Right to Information Act, 2005 (summary). The fee for providing information must be reasonable, and no fee may be charged from persons who are below the poverty line as determined by the appropriate Government. Where a public authority fails to comply with the time limits in Section 7(1), the applicant must be provided the information free of charge. Section 7(4) adds that where access is to be provided to a sensorily disabled person, the PIO must provide assistance to enable access, including assistance appropriate for inspection."),
    ("s7_8_9_rejection_and_form", "Section 7(8) and 7(9), Right to Information Act, 2005 (summary). Where a request is rejected, the PIO must communicate to the applicant the reasons for the rejection, the period within which an appeal against the rejection may be preferred, and the particulars of the appellate authority. Information must ordinarily be provided in the form in which it is sought, unless doing so would disproportionately divert the resources of the public authority or would be detrimental to the safety or preservation of the record in question."),
    ("s8_1_a_to_e", "Section 8(1)(a) to (e), Right to Information Act, 2005 (summary). There is no obligation to give a citizen information whose disclosure would prejudicially affect the sovereignty and integrity of India, the security, strategic, scientific or economic interests of the State, relations with a foreign State, or lead to incitement of an offence (a); information expressly forbidden to be published by a court or tribunal, or whose disclosure may constitute contempt of court (b); information whose disclosure would cause a breach of privilege of Parliament or a State Legislature (c); commercial confidence, trade secrets or intellectual property whose disclosure would harm the competitive position of a third party, unless the competent authority is satisfied that the larger public interest warrants disclosure (d); and information available to a person in a fiduciary relationship, unless the larger public interest warrants disclosure (e)."),
    ("s8_1_f_to_j", "Section 8(1)(f) to (j), Right to Information Act, 2005 (summary). Also exempt: information received in confidence from a foreign Government (f); information whose disclosure would endanger the life or physical safety of any person or identify a confidential source of information for law enforcement or security (g); information which would impede the process of investigation or the apprehension or prosecution of offenders (h); cabinet papers including records of deliberations of the Council of Ministers, Secretaries and other officers, provided that the decisions, their reasons and the material on which they were taken are made public after the decision is taken and the matter is complete (i); and personal information whose disclosure has no relationship to any public activity or interest or would cause an unwarranted invasion of privacy, unless the larger public interest justifies disclosure (j). The proviso to (j) states that information which cannot be denied to Parliament or a State Legislature shall not be denied to any person."),
    ("s8_2_public_interest_override", "Section 8(2), Right to Information Act, 2005 (summary). Notwithstanding anything in the Official Secrets Act, 1923, and notwithstanding any of the exemptions permissible under Section 8(1), a public authority may allow access to information if the public interest in disclosure outweighs the harm to the protected interests. The exemptions are therefore not absolute bars; each requires the authority to weigh the harm of disclosure against the public interest in it."),
    ("s8_3_twenty_year_rule", "Section 8(3), Right to Information Act, 2005 (summary). Subject only to the exemptions in Section 8(1)(a), (c) and (i), any information relating to any occurrence, event or matter which took place twenty years before the date of the request must be provided to the person making the request. Any question about the date from which the twenty years is computed is decided by the Central Government, subject to the usual appeals under the Act. In effect, most exemptions lapse after twenty years; sovereignty and security, legislative privilege and cabinet papers do not."),
    ("s9_copyright", "Section 9, Right to Information Act, 2005 (summary). Without prejudice to Section 8, a PIO may reject a request for information where providing access would involve an infringement of copyright subsisting in a person other than the State. The ground is narrow: it concerns copyright held by a private person, not copyright held by the Government itself, and the PIO may still provide the information in a form that does not infringe."),
    ("s10_severability", "Section 10, Right to Information Act, 2005 (summary). Where a request is rejected on the ground that the information is exempt, access may nevertheless be provided to that part of the record which does not contain exempt information and which can reasonably be severed from the exempt part. When partial access is given, the PIO must give notice stating that only part of the record is being provided, the reasons for the decision including any findings on material questions of fact, the name and designation of the person who made the decision, the fee, and the applicant's rights to review the decision, including the appellate authority, time limit and process."),
    ("s11_third_party", "Section 11, Right to Information Act, 2005 (summary). Where a PIO intends to disclose information which relates to or was supplied by a third party and has been treated as confidential by that third party, the PIO must, within five days of receiving the request, give the third party written notice inviting a submission on whether the information should be disclosed. The third party has ten days from receipt of the notice to make a representation. Disclosure may be allowed if the public interest outweighs the possible harm to the third party, except for trade or commercial secrets protected by law. The PIO must decide within forty days of receiving the request, and the third party may appeal the decision under Section 19."),
    ("s12_13_central_commission", "Sections 12 and 13, Right to Information Act, 2005 (summary). The Central Information Commission consists of the Chief Information Commissioner and up to ten Information Commissioners, appointed by the President on the recommendation of a committee of the Prime Minister (chair), the Leader of Opposition in the Lok Sabha and a Union Cabinet Minister nominated by the Prime Minister. Commissioners must be persons of eminence in public life with wide knowledge and experience, and may not be members of Parliament or a legislature or hold any other office of profit. Since the Right to Information (Amendment) Act, 2019, their term of office and salaries are as prescribed by the Central Government; before that amendment the term was five years and the salary that of the Chief Election Commissioner or an Election Commissioner. A Commissioner is not eligible for reappointment and may not hold office beyond the age of sixty-five."),
    ("s15_16_state_commission", "Sections 15 and 16, Right to Information Act, 2005 (summary). Each State has a State Information Commission consisting of the State Chief Information Commissioner and up to ten State Information Commissioners, appointed by the Governor on the recommendation of a committee of the Chief Minister (chair), the Leader of Opposition in the Legislative Assembly and a Cabinet Minister nominated by the Chief Minister. The eligibility conditions mirror those of the Central Commission. As with the Central Commission, the 2019 amendment moved the term of office and salaries to whatever the Central Government prescribes."),
    ("s18_complaints", "Section 18, Right to Information Act, 2005 (summary). The Central or State Information Commission receives and inquires into a complaint from any person who has been unable to submit a request because no PIO or Assistant PIO has been appointed or the Assistant PIO refused to accept the application; who has been refused access; who has not received a response within the time limits; who has been required to pay a fee they consider unreasonable; who believes the information given is incomplete, misleading or false; or on any other matter relating to requesting or obtaining access. In an inquiry the Commission has the powers of a civil court: summoning persons, requiring documents, receiving evidence on affidavit, requisitioning public records and issuing summons for witnesses. It may examine any record to which the Act applies, notwithstanding any inconsistency in another Act."),
    ("s19_1_2_first_appeal", "Section 19(1) and 19(2), Right to Information Act, 2005 (summary). A person who does not receive a decision within the time specified in Section 7(1), or who is aggrieved by a decision of the PIO, may within thirty days from the expiry of that period or from receipt of the decision prefer an appeal to the officer senior in rank to the PIO in the same public authority (the first appellate authority). The appellate authority may admit a late appeal if satisfied that the appellant was prevented by sufficient cause. Where the appeal is against an order under Section 11 to disclose third-party information, the third party may appeal within thirty days of the order."),
    ("s19_3_second_appeal", "Section 19(3), 19(4) and 19(5), Right to Information Act, 2005 (summary). A second appeal against the decision of the first appellate authority lies to the Central or State Information Commission within ninety days from the date on which the decision should have been made or was actually received; the Commission may admit a late appeal for sufficient cause. Where the appeal concerns third-party information, the Commission must give the third party a reasonable opportunity to be heard. In any appeal proceeding, the onus of proving that a denial of a request was justified is on the PIO who denied it."),
    ("s19_6_8_disposal_and_powers", "Section 19(6) to 19(8), Right to Information Act, 2005 (summary). A first appeal must be disposed of within thirty days of receipt, or within an extended period not exceeding a total of forty-five days from receipt, for reasons recorded in writing. The decision of the Commission is binding. In its decision the Commission may require the public authority to take steps to secure compliance, including providing access in a particular form, appointing a PIO, publishing particular information, making changes to record management practices, enhancing training, or submitting an annual report; it may require the authority to compensate the complainant for any loss or detriment suffered; it may impose the penalties provided in the Act; and it may reject the application."),
    ("s20_penalties", "Section 20, Right to Information Act, 2005 (summary). When deciding a complaint or appeal, if the Commission finds that a PIO has, without reasonable cause, refused to receive an application, failed to furnish information within the time specified in Section 7(1), malafidely denied the request, knowingly given incorrect, incomplete or misleading information, destroyed information that was the subject of the request, or obstructed the furnishing of information in any manner, it must impose a penalty of two hundred and fifty rupees for each day until the application is received or the information is furnished, subject to a maximum of twenty-five thousand rupees. The PIO must be given a reasonable opportunity of being heard, and the burden of proving that the PIO acted reasonably and diligently is on the PIO. For persistent default the Commission must also recommend disciplinary action under the applicable service rules."),
    ("s21_22_23_overriding", "Sections 21, 22 and 23, Right to Information Act, 2005 (summary). No suit, prosecution or other legal proceeding lies against any person for anything done or intended to be done in good faith under the Act. The provisions of the Act have effect notwithstanding anything inconsistent in the Official Secrets Act, 1923, or any other law for the time being in force or any instrument having effect by virtue of such a law. No court may entertain any suit, application or other proceeding in respect of an order made under the Act, and no such order may be questioned otherwise than by way of an appeal under the Act."),
    ("s24_intelligence_exemption", "Section 24, Right to Information Act, 2005 (summary). The Act does not apply to the intelligence and security organisations specified in the Second Schedule, established by the Central Government, nor to information furnished by them to the Government. The exclusion is qualified: information pertaining to allegations of corruption and human rights violations is not excluded, and where the request concerns an allegation of a human rights violation, the information is provided only with the approval of the Central Information Commission, within forty-five days of receipt of the request. State Governments may similarly exclude their own intelligence and security organisations by notification, with the same corruption and human-rights carve-out."),
    ("s25_monitoring_report", "Section 25, Right to Information Act, 2005 (summary). Each Commission prepares an annual report on the implementation of the Act, which the Government lays before Parliament or the State Legislature. Each ministry or department collects from the public authorities under it the number of requests received, the number of decisions refusing access and the provisions relied on, the number of appeals and their outcomes, disciplinary action taken against officers, the charges collected, and recommendations for reform. If the Commission finds that a public authority's practice does not conform to the Act, it may recommend steps to bring it into conformity."),
    ("s26_guides", "Section 26, Right to Information Act, 2005 (summary). The appropriate Government may develop programmes to advance public understanding of how to exercise the rights under the Act, particularly for disadvantaged communities; encourage public authorities to participate; promote timely and effective dissemination of accurate information; and train PIOs. The Government must, within eighteen months of enactment, compile in its official language a guide containing practical information for anyone who wishes to exercise a right under the Act, covering the objects of the Act, contact details of every PIO, the request procedure, the assistance available, fees, remedies, and the exemptions; the guide must be updated at regular intervals."),
    ("s27_28_rule_making", "Sections 27 and 28, Right to Information Act, 2005 (summary). The Central and State Governments may make rules to carry out the Act, including the fee payable with a request, the cost of providing information, the procedure for appeals to the Commission, and the salaries and conditions of Commission staff. Competent authorities (the Speaker of a legislature, the Chief Justice of a court, the President or Governor for their offices, and the administrator of a Union territory) may make rules for the public authorities under them. Rules made by the Central Government are laid before Parliament."),
    ("rules_2012_fees", "Right to Information Rules, 2012 (central rules; summary). The application fee is ten rupees, payable in cash against a receipt, by demand draft or banker's cheque, by Indian Postal Order, or electronically. Further fees: two rupees per page for A4 or A3 copies; the actual cost for larger paper; the actual cost of samples or models; fifty rupees per diskette or floppy; for printed material, the price fixed for the publication, or two rupees per page of a photocopy of extracts; and no fee for the first hour of inspection of records and five rupees for each subsequent hour. Postal charges above fifty rupees may be charged. An application should ordinarily not contain more than five hundred words, excluding annexures, though no application may be rejected only because it exceeds that length. These are the central rules; State Governments and competent authorities make their own, and fees differ from State to State."),
    ("bpl_no_fee", "Fee exemption for BPL applicants (summary). Under Section 7(5) of the Right to Information Act, 2005, no fee, neither the application fee nor the cost of providing information, may be charged from a person who is below the poverty line as determined by the appropriate Government. In practice the applicant attaches proof of BPL status, such as a copy of the BPL card, to the application. A PIO who insists on a fee from a BPL applicant is acting contrary to the Act, and the applicant may complain to the Commission under Section 18."),
    ("timelines_at_a_glance", "Time limits under the Right to Information Act, 2005, at a glance (summary). Transfer of a misdirected application to the right authority: within five days (Section 6(3)). Reply to a request: within thirty days (Section 7(1)); within forty-eight hours where life or liberty is concerned; five additional days where the application was given to an Assistant PIO. Third-party notice: within five days of the request; the third party has ten days to respond; decision within forty days (Section 11). First appeal: within thirty days of the decision or the expiry of the time limit; disposed of within thirty days, extendable to forty-five (Section 19). Second appeal to the Commission: within ninety days (Section 19(3)). Human-rights information from excluded intelligence organisations: within forty-five days, with Commission approval (Section 24). Information about events more than twenty years old: must be provided, subject to three exemptions (Section 8(3))."),
    ("deemed_refusal_what_to_do", "No reply within thirty days (summary). Under Section 7(2) of the Right to Information Act, 2005, a PIO who does not decide a request within the period in Section 7(1) is deemed to have refused it. The applicant need not wait further or send reminders: a deemed refusal may be appealed to the first appellate authority under Section 19(1) within thirty days of the expiry of the period, and under Section 7(6) the information, once provided, must be given free of charge because the time limit was not met. The applicant may also, or instead, complain to the Commission under Section 18 for not receiving a response within the time limit, and the Commission may impose the Section 20 penalty on the PIO."),
    ("case_cbse_answer_sheets", "CBSE v. Aditya Bandopadhyay, Supreme Court of India, 2011 (summary). The Court held that an evaluated answer sheet is 'information' under Section 2(f) and that an examining body does not hold it in a fiduciary relationship with the examiner, so Section 8(1)(e) does not exempt it; a candidate is entitled to inspect and obtain a copy of their own evaluated answer sheet. The Court also observed that the Act does not require a public authority to create information it does not hold, to collect and collate information not available in the form asked for, or to give opinions, advice or answers to hypothetical questions; the right is to information held by the authority, in the form it exists, subject to the exemptions."),
    ("case_girish_deshpande_personal_info", "Girish Ramchandra Deshpande v. Central Information Commission, Supreme Court of India, 2012 (summary). The applicant sought copies of a public servant's memos, show-cause notices, disciplinary orders, asset details and income-tax returns. The Court held that such details are 'personal information' within Section 8(1)(j), that their disclosure has no relationship to any public activity or interest and would amount to an unwarranted invasion of privacy, and that they need not be disclosed unless the PIO or appellate authority is satisfied that the larger public interest justifies it. The decision is regularly cited by PIOs refusing personnel-file requests; the applicant's route is to show the larger public interest."),
    ("case_thalappalam_cooperatives", "Thalappalam Service Cooperative Bank v. State of Kerala, Supreme Court of India, 2013 (summary). The Court held that a cooperative society is not a public authority under Section 2(h) merely because it is registered and regulated under a cooperative societies law; it becomes one only if it is owned, controlled or substantially financed by the Government. 'Substantially financed' means funding of a substantial degree, going to the heart of the body's existence, and not merely a grant or a loan. The Registrar of Cooperative Societies, however, is a public authority, and information which the Registrar can access from a society under the cooperative law may be sought from the Registrar."),
    ("case_cji_office_public_authority", "Central Public Information Officer, Supreme Court of India v. Subhash Chandra Agarwal, Supreme Court of India, 2019 (summary). A Constitution Bench held that the office of the Chief Justice of India is a public authority under the Act and that the Supreme Court and the office of the Chief Justice are not separate public authorities. Information such as the assets declarations of judges is information held by the public authority, subject to the exemptions, in particular Section 8(1)(j) and the balancing of privacy against public interest, and Section 11 where third-party information is involved. The Court stressed that the right to information and the right to privacy are both to be weighed, case by case, and that neither is absolute."),
    ("amendment_2019", "Right to Information (Amendment) Act, 2019 (summary). The amendment changed Sections 13, 16 and 27 of the Act. Before it, the Chief Information Commissioner and Information Commissioners held office for five years (or until sixty-five) and received the salary of the Chief Election Commissioner and Election Commissioners; the State Commissioners were similarly tied to the Election Commissioners and the Chief Secretary. The amendment provides instead that the term of office and the salaries, allowances and conditions of service of the Central and State Commissioners are such as may be prescribed by the Central Government, and empowers the Central Government to make rules for them. The rest of the Act, including the request procedure, time limits, exemptions and penalties, was not amended."),
    ("dpdp_2023_note", "Digital Personal Data Protection Act, 2023, and Section 8(1)(j) (summary and status note). Section 44(3) of the Digital Personal Data Protection Act, 2023 provides for Section 8(1)(j) of the Right to Information Act to be substituted with an exemption for 'information which relates to personal information', without the existing public-interest qualification or the proviso that information which cannot be denied to Parliament cannot be denied to a person. Whether that substitution is in force depends on the notification bringing Section 44(3) into effect, and this note does not track that notification: check the current text of Section 8(1)(j) and the commencement notifications before relying on either version."),
    ("application_checklist", "What an application should contain (guidance summary). The Act prescribes no form. A complete application names the public authority and is addressed to its PIO; states that it is made under Section 6(1) of the Right to Information Act, 2005; describes the specific information or records sought, with the period, precisely enough to be located; states the form in which the information is wanted (copies, inspection, electronic); mentions the fee paid and how, or the BPL proof if exempt; and gives the applicant's name and a postal address for reply. No reason for the request is required (Section 6(2)). The application may be in English, Hindi or the official language of the area."),
    ("inspection_of_records", "Inspection under the Act (summary). The right to information in Section 2(j) includes the right to inspect works, documents and records and to take notes and extracts. An applicant may therefore ask to inspect a file or a public work rather than ask for copies, which is often faster and cheaper for large records. Under the central rules the first hour of inspection is free and each further hour costs five rupees. During inspection the applicant may identify the pages of which certified copies are wanted and pay the per-page fee only for those. A PIO may not refuse inspection merely because copies could be supplied instead, though Section 7(9) allows a different form where the requested form would disproportionately divert resources or harm the record."),
    ("apio_role", "Assistant Public Information Officers (summary). Under Section 5(2) of the Act, every public authority must designate Assistant PIOs at each sub-divisional or sub-district level so that applications and appeals can be filed locally. The Assistant PIO receives the application or appeal and forwards it forthwith to the PIO, the first appellate authority or the Commission, as the case may be. When an application is filed with an Assistant PIO, the proviso to Section 7(1) adds five days to the thirty-day (or forty-eight-hour) limit to allow for the forwarding. Post offices designated as Assistant PIOs by the Department of Posts accept RTI applications for central public authorities."),
]

QA: list[tuple[str, str, str, str]] = [
    ("en", "Within how many days must a PIO reply to an RTI application under Section 7(1)?", "Within thirty days of receipt; within forty-eight hours where life or liberty is concerned.", "s7_1_time_limits"),
    ("hi", "यदि सूचना किसी व्यक्ति के जीवन या स्वतंत्रता से संबंधित हो तो कितने समय में देनी होती है?", "प्राप्ति के 48 घंटे के भीतर (धारा 7(1))।", "s7_1_time_limits"),
    ("en", "What happens if the PIO does not decide the request within the time limit?", "Under Section 7(2) the PIO is deemed to have refused the request.", "s7_1_time_limits"),
    ("hinglish", "RTI application ke saath reason dena zaroori hai kya?", "No. Under Section 6(2) the applicant need not give any reason, nor personal details beyond what is needed for contact.", "s6_2_no_reasons"),
    ("en", "Within how many days must a misdirected RTI application be transferred to the right public authority?", "As soon as practicable and in no case later than five days from receipt, under Section 6(3), with the applicant informed.", "s6_3_transfer"),
    ("hi", "धारा 6(3) के अंतर्गत आवेदन के स्थानांतरण की समय सीमा क्या है?", "प्राप्ति से अधिकतम पाँच दिन, और आवेदक को तुरंत सूचित करना होता है।", "s6_3_transfer"),
    ("en", "In which languages can an RTI application be made?", "In English, Hindi or the official language of the area, in writing or electronically (Section 6(1)).", "s6_1_how_to_apply"),
    ("en", "What must a PIO do if an applicant cannot make the request in writing?", "Render all reasonable assistance to reduce the request to writing (Section 6(1)).", "s6_1_how_to_apply"),
    ("hi", "गरीबी रेखा से नीचे के आवेदक से सूचना का शुल्क लिया जा सकता है क्या?", "नहीं। धारा 7(5) के अंतर्गत गरीबी रेखा से नीचे के व्यक्ति से कोई शुल्क नहीं लिया जा सकता।", "s7_5_6_fee_rules"),
    ("en", "When must information be provided free of charge?", "When the public authority fails to comply with the time limits in Section 7(1) (Section 7(6)).", "s7_5_6_fee_rules"),
    ("hinglish", "Agar PIO application reject kare to usko kya batana padta hai?", "The reasons for rejection, the period within which an appeal may be preferred, and the particulars of the appellate authority (Section 7(8)).", "s7_8_9_rejection_and_form"),
    ("en", "Can a PIO refuse to give information in the form the applicant asked for?", "Only where providing it in that form would disproportionately divert the authority's resources or be detrimental to the safety or preservation of the record (Section 7(9)).", "s7_8_9_rejection_and_form"),
    ("en", "Is information held in a fiduciary relationship always exempt?", "No. Section 8(1)(e) exempts it unless the competent authority is satisfied that the larger public interest warrants disclosure.", "s8_1_a_to_e"),
    ("hi", "धारा 8(1)(j) के अंतर्गत व्यक्तिगत सूचना कब दी जा सकती है?", "जब लोक सूचना अधिकारी या अपीलीय प्राधिकारी संतुष्ट हो कि व्यापक लोकहित उसके प्रकटन को उचित ठहराता है; और जो सूचना संसद या विधानमंडल को देने से मना नहीं की जा सकती, वह किसी व्यक्ति को भी मना नहीं की जा सकती।", "s8_1_f_to_j"),
    ("en", "Are cabinet papers permanently exempt from disclosure?", "No. Under Section 8(1)(i) the decisions of the Council of Ministers, their reasons and the material on which they were taken are made public after the decision is taken and the matter is complete.", "s8_1_f_to_j"),
    ("hinglish", "Official Secrets Act ke against RTI mein disclosure ho sakta hai?", "Yes. Under Section 8(2) a public authority may allow access notwithstanding the Official Secrets Act, 1923 or the Section 8(1) exemptions if the public interest in disclosure outweighs the harm.", "s8_2_public_interest_override"),
    ("en", "Which exemptions survive the twenty-year rule in Section 8(3)?", "Section 8(1)(a) sovereignty and security, 8(1)(c) legislative privilege and 8(1)(i) cabinet papers; other information about matters twenty years old must be provided.", "s8_3_twenty_year_rule"),
    ("hi", "बीस वर्ष पुरानी घटना से संबंधित सूचना देने का नियम क्या है?", "धारा 8(3) के अंतर्गत, केवल 8(1)(a), (c) और (i) की छूटों को छोड़कर, बीस वर्ष पहले की किसी घटना या मामले से संबंधित सूचना देनी ही होती है।", "s8_3_twenty_year_rule"),
    ("en", "On what ground does Section 9 allow rejection of a request?", "Where providing access would infringe copyright subsisting in a person other than the State.", "s9_copyright"),
    ("en", "If part of a record is exempt, can the rest be given?", "Yes. Section 10 allows access to the part that does not contain exempt information and can reasonably be severed, with a notice giving the reasons, the decision-maker, the fee and the review rights.", "s10_severability"),
    ("hinglish", "Third party ko notice kitne din mein dena hota hai aur usko reply ke liye kitne din milte hain?", "Notice within five days of the request; the third party has ten days to make a representation; the PIO decides within forty days (Section 11).", "s11_third_party"),
    ("en", "Who appoints the Central Information Commissioners and on whose recommendation?", "The President, on the recommendation of a committee of the Prime Minister (chair), the Leader of Opposition in the Lok Sabha and a Union Cabinet Minister nominated by the Prime Minister.", "s12_13_central_commission"),
    ("hi", "राज्य सूचना आयोग में अधिकतम कितने राज्य सूचना आयुक्त हो सकते हैं?", "राज्य मुख्य सूचना आयुक्त के अलावा अधिकतम दस राज्य सूचना आयुक्त।", "s15_16_state_commission"),
    ("en", "What did the 2019 amendment to the RTI Act change?", "Sections 13, 16 and 27: the term of office and salaries of Central and State Information Commissioners are now as prescribed by the Central Government, instead of a fixed five-year term and salaries tied to the Election Commissioners.", "amendment_2019"),
    ("en", "Can a person complain to the Information Commission if no PIO has been appointed?", "Yes. Section 18 covers a person unable to submit a request because no PIO or Assistant PIO has been appointed, among other grounds.", "s18_complaints"),
    ("hinglish", "Commission ke paas inquiry mein kaunse powers hote hain?", "The powers of a civil court: summoning persons, requiring documents, receiving evidence on affidavit, requisitioning public records and issuing summons for witnesses (Section 18).", "s18_complaints"),
    ("en", "Within how many days must a first appeal be filed, and to whom?", "Within thirty days of the decision or the expiry of the time limit, to the officer senior in rank to the PIO in the same public authority (Section 19(1)).", "s19_1_2_first_appeal"),
    ("hi", "द्वितीय अपील कितने दिनों के भीतर और किसके पास की जाती है?", "निर्णय की तारीख या जिस तारीख को निर्णय होना चाहिए था, उससे नब्बे दिनों के भीतर केंद्रीय या राज्य सूचना आयोग के पास (धारा 19(3))।", "s19_3_second_appeal"),
    ("en", "In an appeal, who has to prove that a denial of information was justified?", "The PIO who denied the request (Section 19(5)).", "s19_3_second_appeal"),
    ("en", "Within what time must a first appellate authority dispose of an appeal?", "Within thirty days of receipt, extendable for recorded reasons to a total of forty-five days (Section 19(6)).", "s19_6_8_disposal_and_powers"),
    ("hinglish", "Commission complainant ko compensation dila sakta hai kya?", "Yes. Under Section 19(8) the Commission may require the public authority to compensate the complainant for any loss or other detriment suffered.", "s19_6_8_disposal_and_powers"),
    ("en", "What is the daily penalty on a PIO under Section 20 and its maximum?", "Two hundred and fifty rupees per day until the application is received or the information furnished, up to twenty-five thousand rupees.", "s20_penalties"),
    ("hi", "धारा 20 के अंतर्गत जुर्माना लगाने से पहले लोक सूचना अधिकारी को क्या अवसर दिया जाता है?", "सुनवाई का उचित अवसर; और यह सिद्ध करने का भार कि उसने युक्तियुक्त और तत्परता से कार्य किया, अधिकारी पर होता है।", "s20_penalties"),
    ("en", "Does the RTI Act override the Official Secrets Act?", "Yes. Under Section 22 the Act has effect notwithstanding anything inconsistent in the Official Secrets Act, 1923 or any other law.", "s21_22_23_overriding"),
    ("en", "Can an order under the RTI Act be challenged in a civil court?", "No. Under Section 23 no court may entertain a suit or proceeding in respect of an order under the Act, which may be questioned only by appeal under the Act.", "s21_22_23_overriding"),
    ("hinglish", "Intelligence agencies se corruption ke allegations ki information mil sakti hai?", "Yes. Section 24 excludes the listed intelligence and security organisations, but information about allegations of corruption and human rights violations is not excluded.", "s24_intelligence_exemption"),
    ("en", "How long does an excluded intelligence organisation have to provide information about a human rights violation allegation?", "Forty-five days from receipt of the request, and only with the approval of the Central Information Commission (Section 24).", "s24_intelligence_exemption"),
    ("hi", "केंद्रीय आरटीआई नियम, 2012 के अंतर्गत आवेदन शुल्क कितना है?", "दस रुपये, नकद, डिमांड ड्राफ्ट, बैंकर चेक, भारतीय पोस्टल ऑर्डर या इलेक्ट्रॉनिक रूप से।", "rules_2012_fees"),
    ("en", "What is the per-page fee for A4 copies under the central RTI Rules, 2012?", "Two rupees per page.", "rules_2012_fees"),
    ("en", "Is there a word limit on an RTI application under the central rules?", "An application should ordinarily not exceed five hundred words excluding annexures, but it may not be rejected only for exceeding that length.", "rules_2012_fees"),
    ("hinglish", "Records inspect karne ki fees kya hai?", "Under the central rules the first hour of inspection is free and each subsequent hour costs five rupees.", "inspection_of_records"),
    ("en", "What can an applicant do when thirty days pass with no reply?", "Treat it as a deemed refusal under Section 7(2): file a first appeal under Section 19(1) within thirty days, or complain to the Commission under Section 18; the information, when given, must be free under Section 7(6).", "deemed_refusal_what_to_do"),
    ("hi", "क्या परीक्षार्थी अपनी मूल्यांकित उत्तर पुस्तिका की प्रति आरटीआई से ले सकता है?", "हाँ। सीबीएसई बनाम आदित्य बंदोपाध्याय (2011) में सर्वोच्च न्यायालय ने माना कि मूल्यांकित उत्तर पुस्तिका 'सूचना' है और धारा 8(1)(e) के अंतर्गत छूट प्राप्त नहीं है।", "case_cbse_answer_sheets"),
    ("en", "Does the RTI Act require a public authority to answer hypothetical questions or give opinions?", "No. In CBSE v. Aditya Bandopadhyay the Supreme Court observed that the Act does not require an authority to create information, collate information not held in that form, or give opinions or answers to hypothetical questions.", "case_cbse_answer_sheets"),
    ("en", "According to the Supreme Court in Girish Ramchandra Deshpande, are a public servant's income-tax returns and disciplinary records disclosable under RTI?", "Generally no: they are personal information under Section 8(1)(j) and need not be disclosed unless the larger public interest justifies it.", "case_girish_deshpande_personal_info"),
    ("hinglish", "Cooperative society RTI ke under public authority hai kya?", "Not merely because it is registered under a cooperative law; per Thalappalam (2013) it is a public authority only if owned, controlled or substantially financed by the Government.", "case_thalappalam_cooperatives"),
    ("en", "Is the office of the Chief Justice of India a public authority under the RTI Act?", "Yes. In CPIO, Supreme Court v. Subhash Chandra Agarwal (2019) a Constitution Bench held that it is, with disclosure subject to the exemptions and the privacy balancing.", "case_cji_office_public_authority"),
    ("en", "What does Section 44(3) of the Digital Personal Data Protection Act, 2023 propose for Section 8(1)(j)?", "To substitute it with an exemption for information which relates to personal information, without the public-interest qualification; whether it is in force depends on the commencement notification, which the note does not track.", "dpdp_2023_note"),
    ("hi", "सहायक लोक सूचना अधिकारी को आवेदन देने पर समय सीमा में कितने दिन जुड़ते हैं?", "पाँच दिन (धारा 7(1) का परंतुक)।", "apio_role"),
    ("en", "Which categories of information must every public authority publish on its own under Section 4(1)(b)?", "Seventeen categories, including its organisation and functions, officers' powers and duties, decision-making procedure, norms, rules and manuals, documents held, budget, subsidy programmes, concessions, the directory and remuneration of officers, and the names of its PIOs.", "s4_publication_list"),
    ("hinglish", "Government ko affected logon ko decisions ke reasons batane padte hain?", "Yes. Section 4(1)(d) requires every public authority to provide reasons for its administrative or quasi-judicial decisions to the affected persons.", "s4_reasons_for_decisions"),
    ("en", "Does the right to information include taking certified samples of material?", "Yes. Section 2(j) includes inspection, notes and extracts, certified copies, certified samples and electronic copies.", "s2_right_to_information"),
    ("hi", "क्या फ़ाइल पर दर्ज टिप्पणियाँ (नोटिंग) 'सूचना' हैं?", "हाँ। धारा 2(f) में राय और सलाह सहित किसी भी रूप की सामग्री शामिल है, इसलिए फ़ाइल नोटिंग सूचना है।", "s2_information"),
    ("en", "Is an NGO that receives government funds a public authority?", "Only if it is substantially financed, directly or indirectly, by Government funds, or owned or controlled by the Government (Section 2(h)).", "s2_public_authority"),
    ("en", "Who may exercise the right to information under Section 3?", "All citizens; the Act does not confer the right on non-citizens.", "s3_citizens"),
    ("hinglish", "Records ko catalogue aur computerise karna public authority ki duty hai?", "Yes. Section 4(1)(a) requires records to be catalogued and indexed and, subject to resources, computerised and networked.", "s4_records_and_proactive"),
    ("en", "What does Section 26 require the Government to compile, and by when?", "A guide in its official language with practical information for exercising rights under the Act, within eighteen months of enactment, updated regularly.", "s26_guides"),
    ("hi", "सूचना आयोग की वार्षिक रिपोर्ट कहाँ रखी जाती है?", "संसद या राज्य विधानमंडल के समक्ष (धारा 25)।", "s25_monitoring_report"),
    ("en", "Who can make rules for the public authorities under a High Court?", "The competent authority, which for a court is the Chief Justice (Section 28).", "s27_28_rule_making"),
]

UNANSWERABLE: list[tuple[str, str]] = [
    ("en", "What is the application fee under the Maharashtra RTI Rules?"),
    ("hi", "केंद्रीय सूचना आयोग का वर्तमान मुख्य सूचना आयुक्त कौन है?"),
    ("en", "How many second appeals were pending before the Central Information Commission last year?"),
    ("hinglish", "RTI application online kis website par file hoti hai?"),
    ("en", "What salary does an Information Commissioner currently receive?"),
    ("hi", "क्या आरटीआई अधिनियम निजी कंपनियों पर सीधे लागू होता है और उसकी धारा कौन सी है?"),
]


def main() -> None:
    docs = []
    for doc_id, text in DOCS:
        n = len(text.split())
        assert 40 <= n <= 180, f"{doc_id}: {n} words (must be one chunk)"
        docs.append({"doc_id": doc_id, "text": text,
                     "source_uri": f"illustrative://in_statute_qa/{doc_id}"})
    CORPUS.write_text("".join(json.dumps(d, ensure_ascii=False) + "\n" for d in docs),
                      encoding="utf-8")
    ids = {d["doc_id"] for d in docs}

    rows = []
    for i, (lang, q, a, doc) in enumerate(QA, start=1):
        assert doc in ids, f"qa {i}: unknown doc {doc}"
        rows.append({"item_id": f"st{i:02d}", "query": q, "item_type": "answerable",
                     "gold_answer": a, "gold_passage_ids": [f"{doc}#0"],
                     "meta": {"language": lang}})
    for j, (lang, q) in enumerate(UNANSWERABLE, start=1):
        rows.append({"item_id": f"stu{j:02d}", "query": q, "item_type": "unanswerable",
                     "gold_answer": None, "gold_passage_ids": [],
                     "meta": {"language": lang}})
    BASE.write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows),
                    encoding="utf-8")

    base_items = load_evalset(str(BASE))
    suite = build_probe_suite(base_items, PROBES)
    save_evalset(base_items + suite.items, str(EVALSET))
    langs = {lang: sum(1 for r in rows if r["meta"]["language"] == lang)
             for lang in ("en", "hi", "hinglish")}
    print(f"wrote {len(docs)} passages, {len(rows)} base items {langs}, "
          f"{len(suite.items)} probes {suite.counts} -> {EVALSET}")


if __name__ == "__main__":
    main()
